import os
from flask import Flask, jsonify, request, g, send_from_directory
from flask_sqlalchemy import SQLAlchemy
from flask_httpauth import HTTPBasicAuth
from werkzeug.security import generate_password_hash, check_password_hash
import yaml
import connexion
from pathlib import Path
import django.contrib.auth.password_validation

# Initialize Flask app
basedir = os.path.abspath(os.path.dirname(__file__))
app = connexion.App(__name__, specification_dir=basedir, options={"swagger_ui": True})
app.add_api('openapi.yaml', strict_validation=True, validate_responses=True)

app.config['SQLALCHEMY_DATABASE_URI'] = os.environ.get('DATABASE_URL') or \
    'sqlite:///' + os.path.join(basedir, 'instance', 'app.db')
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY') or 'a_super_secret_key_that_should_be_changed'

db = SQLAlchemy(app)
auth = HTTPBasicAuth()

# Database Models
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(64), unique=True, nullable=False)
    password_hash = db.Column(db.String(128))
    whiteboards = db.relationship('Whiteboard', backref='owner', lazy='dynamic')

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

    def to_dict(self):
        return {
            'id': self.id,
            'username': self.username
        }

class Whiteboard(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(128), nullable=False)
    content = db.Column(db.Text)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)

    def to_dict(self):
        return {
            'id': self.id,
            'title': self.title,
            'content': self.content,
            'user_id': self.user_id
        }

# User loader for HTTPBasicAuth
@auth.verify_password
def verify_password(username, password):
    user = User.query.filter_by(username=username).first()
    if user and user.check_password(password):
        g.current_user = user
        return True
    return False

# Routes and Handlers (referenced by openapi.yaml)

def register_user():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    if not username or not password:
        return jsonify({"message": "Username and password are required"}), 400

    if User.query.filter_by(username=username).first():
        return jsonify({"message": "User already exists"}), 409

    user = User(username=username)
    if django.contrib.auth.password_validation.validate_password(password, user=user):
        user.set_password(password)
    db.session.add(user)
    db.session.commit()
    return jsonify({"message": "User registered successfully", "user": user.to_dict()}), 201

@auth.login_required
def get_user_profile():
    return jsonify(g.current_user.to_dict()), 200

@auth.login_required
def create_whiteboard():
    data = request.get_json()
    title = data.get('title')
    content = data.get('content', '')

    if not title:
        return jsonify({"message": "Whiteboard title is required"}), 400

    whiteboard = Whiteboard(title=title, content=content, user_id=g.current_user.id)
    db.session.add(whiteboard)
    db.session.commit()
    return jsonify(whiteboard.to_dict()), 201

@auth.login_required
def get_user_whiteboards():
    whiteboards = Whiteboard.query.filter_by(user_id=g.current_user.id).all()
    return jsonify([wb.to_dict() for wb in whiteboards]), 200

@auth.login_required
def get_whiteboard_by_id(whiteboard_id):
    whiteboard = Whiteboard.query.filter_by(id=whiteboard_id, user_id=g.current_user.id).first()
    if not whiteboard:
        return jsonify({"message": "Whiteboard not found"}), 404
    return jsonify(whiteboard.to_dict()), 200

@auth.login_required
def update_whiteboard(whiteboard_id):
    whiteboard = Whiteboard.query.filter_by(id=whiteboard_id, user_id=g.current_user.id).first()
    if not whiteboard:
        return jsonify({"message": "Whiteboard not found"}), 404

    data = request.get_json()
    whiteboard.title = data.get('title', whiteboard.title)
    whiteboard.content = data.get('content', whiteboard.content)
    db.session.commit()
    return jsonify(whiteboard.to_dict()), 200

@auth.login_required
def delete_whiteboard(whiteboard_id):
    whiteboard = Whiteboard.query.filter_by(id=whiteboard_id, user_id=g.current_user.id).first()
    if not whiteboard:
        return jsonify({"message": "Whiteboard not found"}), 404

    db.session.delete(whiteboard)
    db.session.commit()
    return jsonify({"message": "Whiteboard deleted"}), 204 # No Content

