from .models import Document, Signature
from .serializers import DocumentSerializer, SignatureSerializer
from .permissions import IsOwnerOrReadOnly

class DocumentViewSet(viewsets.ModelViewSet):
    serializer_class = DocumentSerializer
    permission_classes = [IsAuthenticated, IsOwnerOrReadOnly]

    def get_queryset(self):
        user = self.request.user
        return Document.objects.filter(
            Q(owner=user) | Q(signatures__signer=user)
        ).distinct().prefetch_related("signatures", "signatures__signer").select_related("owner")

    def perform_create(self, serializer):
        serializer.save(owner=self.request.user)

    @action(detail=True, methods=["post"])
    def sign(self, request, pk=None):
        document = self.get_object()
        data = request.data.get("signature_data", "")
        if not data:
            return Response({"detail": "signature_data is required"}, status=status.HTTP_400_BAD_REQUEST)
        if Signature.objects.filter(document=document, signer=request.user).exists():
            return Response({"detail": "Document already signed by this user"}, status=status.HTTP_400_BAD_REQUEST)
        sig = Signature.objects.create(document=document, signer=request.user, signature_data=data)
        return Response(SignatureSerializer(sig).data, status=status.HTTP_201_CREATED)

class SignatureViewSet(viewsets.ReadOnlyModelViewSet):
    serializer_class = SignatureSerializer
    permission_classes = [IsAuthenticated]

    def get_queryset(self):
        return Signature.objects.filter(signer=self.request.user).select_related("document", "signer")

