using System.ComponentModel.DataAnnotations;

namespace RecipeManager.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class RecipesController : ControllerBase
    {
        private readonly RecipeContext _context;

        public RecipesController(RecipeContext context)
        {
            _context = context;
        }

        [HttpGet]
        public IActionResult GetRecipes(
            [FromQuery] string? cuisine = null,
            [FromQuery] int? maxCookTime = null,
            [FromQuery] string? ingredient = null)
        {
            var query = _context.Recipes.AsQueryable();

            if (!string.IsNullOrEmpty(cuisine))
            {
                if (Enum.TryParse<CuisineType>(cuisine, true, out var cuisineType))
                    query = query.Where(r => r.Cuisine == cuisineType);
                else
                    return BadRequest("Invalid cuisine type");
            }

            if (maxCookTime.HasValue)
                query = query.Where(r => r.CookTimeMinutes <= maxCookTime.Value);

            if (!string.IsNullOrEmpty(ingredient))
                query = query.Where(r => r.Ingredients.Contains(ingredient));

            return Ok(query.ToList());
        }

        [HttpGet("{id}")]
        public IActionResult GetRecipe(int id)
        {
            var recipe = _context.Recipes.Find(id);
            if (recipe == null) return NotFound();

            return Ok(recipe);
        }

        [HttpPost]
        public IActionResult CreateRecipe([FromBody] RecipeInputModel input)
        {
            if (!Enum.IsDefined(typeof(CuisineType), input.Cuisine))
                return BadRequest("Invalid cuisine type");

            var recipe = new Recipe
            {
                Title = input.Title,
                Description = input.Description,
                Ingredients = input.Ingredients ?? new(),
                CookTimeMinutes = input.CookTimeMinutes,
                Cuisine = input.Cuisine
            };

            _context.Recipes.Add(recipe);
            _context.SaveChanges();

            return CreatedAtAction(nameof(GetRecipe), new { id = recipe.Id }, recipe);
        }

        [HttpPut("{id}")]
        public IActionResult UpdateRecipe(int id, [FromBody] RecipeInputModel input)
        {
            var recipe = _context.Recipes.Find(id);
            if (recipe == null) return NotFound();

            if (!Enum.IsDefined(typeof(CuisineType), input.Cuisine))
                return BadRequest("Invalid cuisine type");

            recipe.Title = input.Title;
            recipe.Description = input.Description;
            recipe.Ingredients = input.Ingredients ?? new();
            recipe.CookTimeMinutes = input.CookTimeMinutes;
            recipe.Cuisine = input.Cuisine;

            _context.SaveChanges();
            return Ok(recipe);
        }

        [HttpDelete("{id}")]
        public IActionResult DeleteRecipe(int id)
        {
            var recipe = _context.Recipes.Find(id);
            if (recipe == null) return NotFound();

            _context.Recipes.Remove(recipe);
            _context.SaveChanges();
            return NoContent();
        }
    }

