    {
        int userId = GetUserId();
        using (var cmd = _connection.CreateCommand())
        {
            cmd.CommandText = "INSERT INTO Quizzes (Title, Description, CreatedBy) VALUES (@title, @desc, @userId); SELECT last_insert_rowid();";
            cmd.Parameters.AddWithValue("@title", quiz.Title);
            cmd.Parameters.AddWithValue("@desc", quiz.Description ?? "");
            cmd.Parameters.AddWithValue("@userId", userId);
            long quizId = (long)cmd.ExecuteScalar();
            return Ok(new { Id = quizId });
        }
    }

