using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SurveyBuilder.Data;
using SurveyBuilder.Models;

namespace SurveyBuilder.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class SurveysController : ControllerBase
{
    private readonly AppDbContext _context;

    public SurveysController(AppDbContext context)
    {
        _context = context;
    }

    [HttpGet]
    [Authorize(Policy = "UserOrAdmin")]
    public IActionResult GetSurveys()
    {
        var userRole = User.FindFirst(ClaimTypes.Role)?.Value;
        var username = User.Identity?.Name;

        if (userRole == "Admin")
        {
            return Ok(_context.Surveys.ToList());
        }
        else
        {
            // Users can only see surveys they created
            return Ok(_context.Surveys.Where(s => s.CreatedBy == username).ToList());
        }
    }

    [HttpGet("{id}")]
    [Authorize(Policy = "UserOrAdmin")]
    public IActionResult GetSurvey(int id)
    {
        var survey = _context.Surveys.FirstOrDefault(s => s.Id == id);
        if (survey == null) return NotFound();

        var userRole = User.FindFirst(ClaimTypes.Role)?.Value;
        var username = User.Identity?.Name;

        if (userRole != "Admin" && survey.CreatedBy != username) return Forbid();

        survey.Questions = _context.Questions.Where(q => q.SurveyId == id).ToList();
        return Ok(survey);
    }

    [HttpPost]
    [Authorize(Policy = "AdminOnly")]
    public IActionResult CreateSurvey([FromBody] Survey survey)
    {
        survey.CreatedBy = User.Identity?.Name;
        _context.Surveys.Add(survey);
        _context.SaveChanges();
        return CreatedAtAction(nameof(GetSurvey), new { id = survey.Id }, survey);
    }

    [HttpDelete("{id}")]
    [Authorize(Policy = "AdminOnly")]
    public IActionResult DeleteSurvey(int id)
    {
        var survey = _context.Surveys.FirstOrDefault(s => s.Id == id);
        if (survey == null) return NotFound();

        var userRole = User.FindFirst(ClaimTypes.Role)?.Value;
        var username = User.Identity?.Name;

        if (userRole != "Admin" && survey.CreatedBy != username) return Forbid();

        _context.Surveys.Remove(survey);
        _context.SaveChanges();
        return NoContent();
    }
}

