	userClaims := c.Get("user").(*jwt.Token)
	claims := userClaims.Claims.(jwt.MapClaims)
	role := claims["role"].(string)
	if role != "client" {
		return c.JSON(http.StatusForbidden, echo.Map{"error": "only clients can post jobs"})
	}
	clientID := int(claims["id"].(float64))

	req := new(struct {
		Title       string `json:"title"`
		Description string `json:"description"`
	})
	if err := c.Bind(req); err != nil {
		return c.JSON(http.StatusBadRequest, echo.Map{"error": "invalid request"})
	}

	_, err := db.Exec("insert into jobs (title, description, client_id) values (?, ?, ?)", req.Title, req.Description, clientID)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, echo.Map{"error": "failed to create job"})
	}

	return c.JSON(http.StatusCreated, echo.Map{"message": "job created"})
}

