	rows, err := db.Query("select id, title, description, client_id, freelancer_id, status from jobs")
	if err != nil {
		return c.JSON(http.StatusInternalServerError, echo.Map{"error": "failed to fetch jobs"})
	}
	defer rows.Close()

	var jobs []Job
	for rows.Next() {
		var job Job
