const Koa = require('koa');
const bodyParser = require('koa-bodyparser');
const router = require('./routes');
const { ApolloServer, gql } = require('apollo-server-koa');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('./forum.db');

const app = new Koa();
app.use(bodyParser());

const typeDefs = gql`
  type Post {
    id: ID!
    title: String!
    content: String!
    author: String!
  }

  type Token {
    token: String!
  }

  type Query {
    posts: [Post]
    post(id: ID!): Post
  }

  type Mutation {
    login(username: String!, password: String!): Token
    createPost(title: String!, content: String!, author: String!): Post
  }
`;

const resolvers = {
  Query: {
    posts: () => db.all('SELECT * FROM posts'),
    post: (_, { id }) => db.get('SELECT * FROM posts WHERE id = ?', [id]),
  },
  Mutation: {
    login: async (_, { username, password }) => {
      const user = await db.get('SELECT * FROM users WHERE username = ?', [username]);
      if (!user || !(await bcrypt.compare(password, user.password))) {
        throw new Error('Invalid credentials');
      }
      return { token: jwt.sign({ userId: user.id }, 'secret') };
    },
    createPost: (_, { title, content, author }) => {
      db.run('INSERT INTO posts (title, content, author) VALUES (?, ?, ?)', [title, content, author]);
      return { title, content, author };
    },
  },
};

const server = new ApolloServer({ typeDefs, resolvers });
server.applyMiddleware({ app });

app.use(server.getMiddleware());
app.use(router.routes());

app.listen(8000, () => {
  console.log('Server is running on port 8000');
});

