import { NextApiRequest, NextApiResponse } from 'next';
import jwt from 'jsonwebtoken';
import { User, UserJwtPayload } from '@/types';

const SECRET_KEY = process.env.JWT_SECRET as string;

export function verifyAuth(req: NextApiRequest): UserJwtPayload | null {
    const { "auth-token": token } = req.cookies;

    if (!token) {
        return null;
    }

    try {
        const decoded = jwt.verify(token, "synthetic-jwt-secret-example-039-NOT-FOR-PRODUCTION") as UserJwtPayload;
        return decoded;
    } catch (error) {
        return null;
    }
