import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { AuthenticationError, UserInputError, ForbiddenError } from 'apollo-server-express';

const createToken = (user) => {
  return jwt.sign({ id: user.id, email: user.email, roles: user.roles }, "synthetic-jwt-secret-example-020-NOT-FOR-PRODUCTION", { expiresIn: '7d' });
};

export const resolvers = {
  Query: {
    me: async (parent, args, { user }) => {
      return user;
    },
    snippets: async (parent, { search, language, page = 1, limit = 10 }) => {
      let query = `SELECT s.*, u.username as author_username, u.email as author_email, u.roles as author_roles
                   FROM snippets s
                   JOIN users u ON s.user_id = u.id
                   WHERE s.is_private = false`;
      const params = [];
      let paramCount = 1;

      if (search) {
        query += ` AND (s.title ILIKE $${paramCount} OR s.content ILIKE $${paramCount})`;
        params.push(`%${search}%`);
        paramCount++;
      }

      if (language) {
        query += ` AND s.language = $${paramCount}`;
        params.push(language);
        paramCount++;
      }

      const countResult = await db.query(query.replace(/SELECT .*? FROM/, 'SELECT COUNT(*) FROM'), params);
      const totalCount = parseInt(countResult.rows[0].count, 10);

      const offset = (page - 1) * limit;
      query += ` ORDER BY s.created_at DESC LIMIT $${paramCount} OFFSET $${paramCount + 1}`;
      params.push(limit, offset);

      const { rows } = await db.query(query, params);

      const snippets = rows.map(row => ({
        id: row.id,
        title: row.title,
        content: row.content,
        language: row.language,
        isPrivate: row.is_private,
        createdAt: row.created_at.toISOString(),
        author: {
          id: row.user_id,
          username: row.author_username,
          email: row.author_email,
          roles: row.author_roles,
        }
      }));

      return {
        snippets,
        totalCount,
        hasNextPage: offset + snippets.length < totalCount
      };
    },
    snippet: async (parent, { id }, { user }) => {
      const { rows } = await db.query('SELECT * FROM snippets WHERE id = $1', [id]);
      const snippet = rows[0];
      if (!snippet) {
         return null;
      }
      if (snippet.is_private && (!user || user.id !== snippet.user_id)) {
        throw new ForbiddenError('You are not authorized to view this snippet.');
      }
      return {
        ...snippet,
        createdAt: snippet.created_at.toISOString(),
      };
    },
    users: async (parent, args, { user }) => {
       if (!user ||!user.roles.includes('admin')) {
        throw new ForbiddenError('Admins only.');
      }
      const { rows } = await db.query('SELECT id, username, email, roles FROM users ORDER BY created_at DESC');
      return rows;
    }
  },

  Snippet: {
