      let where = "";
      const params: any[] = [];
      if (search) {
        where = "WHERE comment LIKE ? OR score = ?";
        params.push(`%${search}%`, Number(search) || 0);
      }
      const items = await dbAll(
        `SELECT f.id, f.score, f.comment, f.createdAt, u.id as userId, u.email, u.role
         FROM feedback f JOIN users u ON f.userId = u.id
         ${where} ORDER BY f.createdAt DESC LIMIT ? OFFSET ?`,
        [...params, limit, offset]
      );
      const totalRow = await dbGet(`SELECT COUNT(*) as c FROM feedback f ${where}`, params);
      return {
        items: items.map((r) => ({ ...r, user: { id: r.userId, email: r.email, role: r.role } })),
        total: totalRow.c,
      };
    },
    feedback: async (_: any, { id }: any) => {
      const row = await dbGet(
        `SELECT f.id, f.score, f.comment, f.createdAt, u.id as userId, u.email, u.role
         FROM feedback f JOIN users u ON f.userId = u.id WHERE f.id = ?`,
        [id]
      );
      if (!row) return null;
      return { ...row, user: { id: row.userId, email: row.email, role: row.role } };
    },
    me: (_: any, __: any, { user }: Context) => user,
  },
  Mutation: {
    signup: async (_: any, { email, password, role = "USER" }: any) => {
      const exists = await dbGet("SELECT id FROM users WHERE email = ?", [email]);
      if (exists) throw new Error("Email taken");
      const hash = await bcrypt.hash(password, 10);
