      const row = await dbGet("SELECT id, password, role FROM users WHERE email = ?", [email]);
      if (!row) throw new Error("Invalid credentials");
      const valid = await bcrypt.compare(password, row.password);
      if (!valid) throw new Error("Invalid credentials");
      const user = { id: row.id, email, role: row.role };
      const token = jwt.sign({ sub: user.id }, process.env.JWT_SECRET!);
      return { token, user };
    },
    createFeedback: async (_: any, { score, comment }: any, { user }: Context) => {
      if (!user) throw new Error("Unauthorized");
      const { lastID } = await dbRun("INSERT INTO feedback (score, comment, userId) VALUES (?,?,?)", [score, comment || null, user.id]);
      const row = await dbGet("SELECT id, score, comment, createdAt FROM feedback WHERE id = ?", [lastID]);
      return { ...row, user };
    },
    updateFeedback: async (_: any, { id, score, comment }: any, { user }: Context) => {
      if (!user) throw new Error("Unauthorized");
      const existing = await dbGet("SELECT userId FROM feedback WHERE id = ?", [id]);
      if (!existing) throw new Error("Not found");
