      const sets: string[] = [];
      const params: any[] = [];
      if (score !== undefined) {
        sets.push("score = ?");
        params.push(score);
      }
      if (comment !== undefined) {
        sets.push("comment = ?");
        params.push(comment);
      }
      if (!sets.length) throw new Error("No fields to update");
      params.push(id);
      await dbRun(`UPDATE feedback SET ${sets.join(", ")} WHERE id = ?`, params);
      const row = await dbGet("SELECT id, score, comment, createdAt FROM feedback WHERE id = ?", [id]);
      return { ...row, user };
    },
    deleteFeedback: async (_: any, { id }: any, { user }: Context) => {
      if (!user) throw new Error("Unauthorized");
      if (user.role !== "ADMIN") throw new Error("Forbidden");
      const { changes } = await dbRun("DELETE FROM feedback WHERE id = ?", [id]);
      return changes === 1;
    },
  },
};

