from ariadne import ObjectType, QueryType, MutationType, make_executable_schema
from ariadne.asgi import GraphQL
import aiosqlite
import os
from models import User, Product
from auth import create_token, verify_token, check_permissions

query = QueryType()
mutation = MutationType()

db_path = os.getenv('DATABASE_URL', 'warehouse.db').replace('sqlite:///', '')

async def get_db():
    return await aiosqlite.connect(db_path)

@query.field("products")
async def resolve_products(*_, offset=0, limit=10, search=None, filterLocation=None, info):
    user = info.context.get('user')
    if not user or not check_permissions(user['role'], 'worker'):
        raise Exception("Authentication required")
    async with await get_db() as db:
        products = await Product.get_all(db, offset=offset, limit=limit, search=search, filter_location=filterLocation)
        total = await Product.get_total_count(db, search=search, filter_location=filterLocation)
        return {
            'products': [dict(id=p.id, name=p.name, description=p.description, quantity=p.quantity, location=p.location) for p in products],
            'totalCount': total,
            'hasNextPage': (offset + limit) < total
        }

@query.field("product")
async def resolve_product(*_, id, info):
    user = info.context.get('user')
    if not user or not check_permissions(user['role'], 'worker'):
        raise Exception("Authentication required")
    async with await get_db() as db:
        async with db.execute('SELECT id, name, description, quantity, location FROM products WHERE id = ?', (id,)) as cursor:
            row = await cursor.fetchone()
            if row:
                p = Product(*row)
                return dict(id=p.id, name=p.name, description=p.description, quantity=p.quantity, location=p.location)
            return None

@mutation.field("login")
async def resolve_login(*_, username, password):
    from passlib.hash import argon2
    async with await get_db() as db:
        user = await User.get_by_username(db, username)
        if user and argon2.verify(password, user.password_hash):
            token = create_token(user)
            return {'token': token, 'user': {'username': user.username, 'role': user.role}}
        raise Exception("Invalid credentials")

@mutation.field("createProduct")
async def resolve_create_product(*_, input, info):
    user = info.context.get('user')
    if not user or not check_permissions(user['role'], 'manager'):
        raise Exception("Insufficient permissions")
    async with await get_db() as db:
        product = await Product.create(db, input['name'], input['description'], input['quantity'], input['location'])
        return dict(id=product.id, name=product.name, description=product.description, quantity=product.quantity, location=product.location)

