import psycopg2.extras
from datetime import datetime, timedelta, timezone
from functools import wraps
from flask import Flask, request, jsonify
from passlib.context import CryptContext
from dotenv import load_dotenv

load_dotenv(os.path.expanduser("~/.env"))
DATABASE_URL = os.getenv("DATABASE_URL")
SECRET_KEY   = os.getenv("SECRET_KEY")
ALGORITHM    = "HS256"

app = Flask(__name__)
pwd = CryptContext(schemes=["bcrypt"], deprecated="auto")

def get_db():
    return psycopg2.connect(DATABASE_URL)

def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return jsonify({"error": "Token gerekli"}), 401
        try:
            token = auth.split(" ")[1]
            payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
            request.user_id = int(payload["sub"])
        except:
            return jsonify({"error": "Geçersiz veya süresi dolmuş token"}), 401
        return f(*args, **kwargs)
    return decorated

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.json
    conn = get_db()
    try:
        cur = conn.cursor()
        hashed = pwd.hash(data['password'])
        cur.execute(
            "INSERT INTO users (username, email, password_hash) VALUES (%s, %s, %s) RETURNING id",
            (data['username'], data['email'], hashed)
        )
        uid = cur.fetchone()[0]
        conn.commit()
        token = jwt.encode({"sub": str(uid), "exp": datetime.now(timezone.utc) + timedelta(days=1)}, SECRET_KEY, algorithm=ALGORITHM)
        return jsonify({"token": token}), 201
    except Exception as e:
        return jsonify({"error": str(e)}), 400
    finally:
        conn.close()

@app.route("/auth/login", methods=["POST"])
def login():
    data = request.json
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    cur.execute("SELECT * FROM users WHERE email = %s", (data['email'],))
    user = cur.fetchone()
    conn.close()
    if user and pwd.verify(data['password'], user['password_hash']):
        token = jwt.encode({"sub": str(user['id']), "exp": datetime.now(timezone.utc) + timedelta(days=1)}, SECRET_KEY, algorithm=ALGORITHM)
        return jsonify({"token": token})
    return jsonify({"error": "Hatalı bilgiler"}), 401

@app.route("/notes", methods=["GET", "POST"])
@login_required
def notes_main():
    conn = get_db()
    cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
    if request.method == "GET":
        cur.execute("SELECT * FROM notes WHERE user_id = %s ORDER BY created_at DESC", (request.user_id,))
        notes = [dict(n) for n in cur.fetchall()]
        for n in notes:
            n["created_at"] = str(n["created_at"])
            n["updated_at"] = str(n["updated_at"])
        conn.close()
        return jsonify(notes)

    data = request.json
    cur.execute(
        "INSERT INTO notes (user_id, title, content) VALUES (%s, %s, %s) RETURNING *",
        (request.user_id, data['title'], data['content'])
    )
    conn.commit()
    conn.close()
    return jsonify({"status": "ok"}), 201

@app.route("/notes/<int:nid>", methods=["PUT", "DELETE"])
@login_required
def note_ops(nid):
    conn = get_db()
    cur = conn.cursor()
    if request.method == "DELETE":
        cur.execute("DELETE FROM notes WHERE id = %s AND user_id = %s", (nid, request.user_id))
        conn.commit()
        conn.close()
        return jsonify({"status": "silindi"})

    data = request.json
    cur.execute(
        "UPDATE notes SET title=%s, content=%s, updated_at=NOW() WHERE id=%s AND user_id=%s",
        (data['title'], data['content'], nid, request.user_id)
    )
    conn.commit()
    conn.close()
    return jsonify({"status": "güncellendi"})

